'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export async function toggleNotification() {
  const cookieStore = await cookies()
  const currentPref = cookieStore.get('notifications')?.value

  const newPref = currentPref === 'on' ? 'off' : 'on'

  cookieStore.set('notifications', newPref)

  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotification } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const currentPref = cookieStore.get('notifications')?.value || 'off'

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Settings</h1>

      <p style={{ fontSize: '1.25rem' }}>
        Notifications are currently: <strong>{currentPref.toUpperCase()}</strong>
      </p>

      <form action={toggleNotification} style={{ marginTop: '1rem' }}>
        <button 
          type="submit" 
          style={{ 
            padding: '0.5rem 1rem', 
            fontSize: '1rem', 
            cursor: 'pointer',
            backgroundColor: currentPref === 'on' ? '#dc2626' : '#16a34a',
            color: 'white',
            border: 'none',
            borderRadius: '4px'
          }}
        >
          Turn {currentPref === 'on' ? 'Off' : 'On'} Notifications
        </button>
      </form>
    </main>
  );
}
